<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { api, post } from '../api'
import LegacyIcon from './LegacyIcon.vue'
interface Feature { feature: string; label: string; path: string; files: number; bytes: number; sessions?: number; error: string }
interface Discovery { features: Feature[]; historical: { path: string }[]; session_backend: string; transfer_available: boolean }
interface Preview { features: string[]; dependencies: string[]; sessions: number; files: number; bytes: number; blockers: string[] }
interface Operation { id: string; status: string; created_at: string; error?: string; download_url?: string; recovery_path?: string }
interface Workspace { workspace_id: string; display_name: string; archived?: boolean }
const workspaces = ref<Workspace[]>([])
const source = ref('')
const target = ref('')
const discovery = ref<Discovery | null>(null)
const selected = ref<string[]>([])
const preview = ref<Preview | null>(null)
const operations = ref<Operation[]>([])
const historical = ref(false)
const busy = ref(false)
const error = ref('')
let timer: ReturnType<typeof setInterval> | undefined
const labels: Record<string, string> = { chat: '对话', book: '书籍', learning: '掌握路径', reading: '沉浸式阅读', timed_media: '沉浸式观看', notebook: '笔记本', 'co-writer': '协作写作', learning_journal: '学习日志', files: '文件库', knowledge_bases: '知识库', parse_cache: '文档解析缓存', outputs: '生成产物', presentations: '已展示文件', attachments: '对话附件', historical_chat: '历史对话数据库', historical_agent: '历史智能体产物', historical_output: '历史输出目录', historical_archive: '历史归档' }
const label = (key: string) => labels[key] || key
const statusLabel = (key: string) => ({ preparing: '准备中', copying: '复制中', transferring: '迁移中', committed: '收尾中', completed: '已完成', exported: '已导出', recovered: '已恢复', failed: '失败，来源数据已保留', cleanup_required: '需要完成清理', recovery_required: '需要恢复' } as Record<string, string>)[key] || key
const input = computed(() => ({ source_workspace_id: source.value, target_workspace_id: target.value, features: selected.value, include_historical: historical.value }))
function toggle(feature: string) { selected.value = selected.value.includes(feature) ? selected.value.filter(item => item !== feature) : [...selected.value, feature]; preview.value = null }
async function loadDiscovery() { discovery.value = null; selected.value = []; error.value = ''; try { const result = await api<Discovery>(`/api/settings/workspace/data/discover?source_workspace_id=${encodeURIComponent(source.value)}`); discovery.value = { ...result, historical: result.historical || [], features: result.features || [] } } catch (cause) { error.value = cause instanceof Error ? cause.message : '数据发现失败' } }
async function loadOperations() { try { operations.value = (await api<{ operations: Operation[] }>('/api/settings/workspace/data/operations')).operations } catch { operations.value = [] } }
async function run(action: 'preview' | 'migrate' | 'export') { busy.value = true; error.value = ''; try { if (action === 'preview') { const result = await post<Preview>('/api/settings/workspace/data/preview', input.value); preview.value = { ...result, dependencies: result.dependencies || [], blockers: result.blockers || [], features: result.features || [] } } else { const result = await post<Operation>(`/api/settings/workspace/data/${action}`, input.value); operations.value = [result, ...operations.value]; if (action === 'migrate') { preview.value = null; selected.value = []; await loadDiscovery() } } } catch (cause) { error.value = cause instanceof Error ? cause.message : '操作失败' } finally { busy.value = false } }
async function recover(id: string) { busy.value = true; error.value = ''; try { const result = await post<Operation>(`/api/settings/workspace/data/operations/${encodeURIComponent(id)}/recover`, {}); operations.value = operations.value.map(row => row.id === id ? result : row) } catch (cause) { error.value = cause instanceof Error ? cause.message : '恢复失败' } finally { busy.value = false } }
onMounted(async () => { try { workspaces.value = (await api<{ workspaces: Workspace[] }>('/api/settings/workspace/registrations')).workspaces; source.value = workspaces.value[0]?.workspace_id || ''; await Promise.all([loadDiscovery(), loadOperations()]); timer = setInterval(loadOperations, 5000) } catch (cause) { error.value = cause instanceof Error ? cause.message : '工作区加载失败' } })
onUnmounted(() => { if (timer) clearInterval(timer) })
</script>
<template><section class="data-migration-settings"><header class="legacy-settings-page-header"><h1>数据迁移</h1><p>查找已有学习数据，将资料和关联对话一并迁移，或下载备份。迁移后会保留经过校验的恢复副本。</p></header><p class="muted">学习数据按功能整体迁移，预览会列出关联资料和对话。目标工作区中对应功能应为空，以免覆盖已有学习记录。</p><p v-if="selected.some(key => key.startsWith('historical_'))" class="muted">历史数据将作为档案保存在目标工作区内，不会自动合并到当前学习记录。</p><p v-if="discovery?.transfer_available === false" class="data-migration-warning">PostgreSQL 工作区暂不支持功能包迁移。现有对话和文件仍可访问。</p><fieldset :disabled="busy"><div class="data-migration-selects"><label>来源工作区<select v-model="source" @change="loadDiscovery"><option v-for="workspace in workspaces.filter(row => !row.archived)" :key="workspace.workspace_id" :value="workspace.workspace_id">{{ workspace.display_name }}</option></select></label><label>目标工作区<select v-model="target" @change="preview = null"><option value="">默认工作区</option><option v-for="workspace in workspaces.filter(row => !row.archived)" :key="workspace.workspace_id" :value="workspace.workspace_id">{{ workspace.display_name }}</option></select></label></div><section v-if="discovery" class="data-migration-features"><h2>选择要迁移的数据</h2><label v-for="feature in discovery.features" :key="feature.feature" class="data-migration-feature"><input type="checkbox" :checked="selected.includes(feature.feature)" @change="toggle(feature.feature)"><span><strong>{{ label(feature.feature) }}</strong><small>{{ feature.files }} 个文件<template v-if="feature.sessions"> · {{ feature.sessions }} 个对话</template> · {{ (feature.bytes / 1024 / 1024).toFixed(1) }} MB</small><small v-if="feature.error" class="error">{{ feature.error }}</small></span></label><label v-if="discovery.historical.length" class="data-migration-historical"><input v-model="historical" type="checkbox" @change="preview = null">包含历史归档（{{ discovery.historical.length }} 个目录）</label></section><div class="data-migration-actions"><button :disabled="!selected.length" @click="run('preview')"><LegacyIcon name="history" :size="14" />预览迁移</button><button :disabled="!selected.length" @click="run('export')"><LegacyIcon name="save" :size="14" />导出所选数据</button></div><div v-if="preview" class="data-migration-preview"><p>{{ preview.sessions }} 个对话 · {{ preview.files }} 个文件 · {{ (preview.bytes / 1024 / 1024).toFixed(1) }} MB</p><p>包含功能：{{ preview.features.map(label).join('、') }}</p><p v-if="preview.dependencies.length" class="muted">为保留引用，额外包含关联来源数据：{{ preview.dependencies.map(label).join('、') }}</p><p v-for="reason in preview.blockers" :key="reason" class="error">{{ reason }}</p><button class="primary" :disabled="preview.blockers.length > 0" @click="run('migrate')"><LegacyIcon name="folder" :size="14" />迁移以上数据</button></div></fieldset><p v-if="busy" role="status">正在处理。可以稍后回到此页查看结果。</p><p v-if="error" class="error" role="alert">{{ error }}</p><section v-if="operations.length" class="data-migration-operations"><h2>最近操作</h2><article v-for="row in operations.slice(0, 10)" :key="row.id"><p>{{ statusLabel(row.status) }} · {{ new Date(row.created_at).toLocaleString('zh-CN') }}</p><p v-if="row.error" class="error">{{ row.error }}</p><a v-if="row.download_url" :href="row.download_url"><LegacyIcon name="save" :size="12" />下载备份</a><button v-if="!['completed', 'exported', 'recovered'].includes(row.status)" :disabled="busy || discovery?.transfer_available === false" @click="recover(row.id)">恢复迁移</button><p v-if="row.recovery_path" class="muted">恢复副本：{{ row.recovery_path }}</p></article></section></section></template>
